htmlform.script:
$j(function() {
    // The diagnosis of the previous biopsy is asked for, and required, only when there was a previous biopsy
    // (1065 = Yes, 1066 = No)
    var showPreviousBiopsyDiagnosis = function() {
        var answer = getValue('previousBiopsy.value');
        if (answer == 1066) {
            setValue('previousBiopsyDiagnosis.value', '');
        }
        $j('#previousBiopsyDiagnosis :input').prop('disabled', answer == 1066);
        $j('#previousBiopsyDiagnosisRequired').toggle(answer == 1065);
    };
    $j('#previousBiopsy :radio').change(showPreviousBiopsyDiagnosis);
    showPreviousBiopsyDiagnosis();
    beforeSubmit.push(function() {
        if (getValue('previousBiopsy.value') == 1065 && $j.trim(getValue('previousBiopsyDiagnosis.value') || '') == '') {
            getField('previousBiopsyDiagnosis.error').html('Required when there was a previous biopsy').show();
            return false;
        }
        getField('previousBiopsyDiagnosis.error').html('').hide();
        return true;
    });

    // A request needs at least one pathology test: one added with "New Order", or one already saved on this
    // encounter that is not being deleted
    var countPathologyTests = function() {
        var count = 0;
        $j('#pathologyTests .orderwidget-new-order-section .orderwidget-orderable-section').each(function() {
            var section = $j(this);
            if (section.children('.orderwidget-history-section').length > 0) {
                var deleting = section.find('.order-action-forms .order-field.order-action select').filter(function() {
                    return $j(this).val() == 'DISCONTINUE';
                }).length > 0;
                if (!deleting) {
                    count++;
                }
            }
            else if ($j.trim(section.find('.order-field-widget.order-concept select').val() || '') != '') {
                count++;
            }
        });
        return count;
    };
    beforeSubmit.push(function() {
        if (countPathologyTests() == 0) {
            $j('#pathologyTestsError').show();
            $j('html, body').animate({ scrollTop: $j('#pathologyTests').offset().top - 100 }, 300);
            return false;
        }
        $j('#pathologyTestsError').hide();
        return true;
    });

    $j("#hivstatusentry").hide();
    $j('.disdiv').find('input').attr('disabled', 'true');
    var hivstatus = (document.getElementById('hivstatus').innerHTML).trim();

    if(hivstatus != "POSITIVE") {
        $j("#hivstatusentry").show();
    }
});

if (jQuery) {
    $j(document).ready(function() {
        // No check for Internet Explorer ($j.browser.msie) here: $j.browser does not exist in the jQuery of the
        // patient dashboard, and the error it caused stopped the pathology test orders from being shown
        getField('specimenANonCoded.value')[0].disabled = true;
        getField('specimenBNonCoded.value')[0].disabled = true;
        getField('specimenCNonCoded.value')[0].disabled = true;
        getField('specimenDNonCoded.value')[0].disabled = true;
        getField('hospitalNonCoded.value')[0].disabled = true;

        getField('specimenA.value').change(function() {
            if(getValue('specimenA.value') == $@OTHER_NON_CODED@) {
                getField('specimenANonCoded.value')[0].disabled = false;
            } else {
                getField('specimenANonCoded.value')[0].disabled = true;
            }
        });

        getField('specimenB.value').change(function() {
            if(getValue('specimenB.value') == $@OTHER_NON_CODED@) {
                getField('specimenBNonCoded.value')[0].disabled = false;
            } else {
                getField('specimenBNonCoded.value')[0].disabled = true;
            }
        });

        getField('specimenC.value').change(function() {
            if(getValue('specimenC.value') == $@OTHER_NON_CODED@) {
                getField('specimenCNonCoded.value')[0].disabled = false;
            } else {
                getField('specimenCNonCoded.value')[0].disabled = true;
            }
        });

        getField('specimenD.value').change(function() {
            if(getValue('specimenD.value') == $@OTHER_NON_CODED@) {
                getField('specimenDNonCoded.value')[0].disabled = false;
            } else {
                getField('specimenDNonCoded.value')[0].disabled = true;
            }
        });

        getField('hospital.value').change(function() {
            if(getValue('hospital.value') == $@OTHER_NON_CODED@) {
                getField('hospitalNonCoded.value')[0].disabled = false;
            } else {
                getField('hospitalNonCoded.value')[0].disabled = true;
            }
        });

        $j(".enableDisable").each(function() {
            var group = $j(this);
            function disableFn() {
                group.children("#disabled").fadeTo(250, 0.33);
                group.children("#disabled").find(":checkbox").attr("checked", false);
                group.children("#disabled").find("input[type$='text']").val("");
                group.children("#disabled").find("input").attr("disabled", true);
            }
            function enableFn() {
                group.children("#disabled").fadeTo(250, 1);
                group.children("#disabled").find("input").attr("disabled", false);
            }
            disableFn();
            $j(this).children("#trigger").find(":checkbox:first").change(function() {
                var checked = $j(this).attr("checked");
                if (checked == true) {
                    enableFn();
                } else {
                    disableFn();
                }
            });
        });

        $j(".checkboxGroup").each(function() {
            var group = $j(this);
            var uncheckAll = function() {
                group.find("input[type$='checkbox']").attr("checked", false);
                group.find("input[type$='checkbox']").change();
            }
            var uncheckRadioAndAll = function() {
                group.find("#checkboxAll,#checkboxRadio").find("input[type$='checkbox']").attr("checked", false);
                group.find("#checkboxAll,#checkboxRadio").find("input[type$='checkbox']").change();
            }

            group.find("#checkboxAll").find("input").click(function() {
                var flip;
                var checked = $j(this).siblings(":checkbox:first").attr("checked");
                if ($j(this).attr("name") == $j(this).parents("#checkboxAll:first").find(":checkbox:first").attr("name")) {
                    checked = $j(this).attr("checked");
                    flip = checked;
                } else {
                    flip = !checked;
                }
                if ($j(this).attr("type") == "text")
                    if (flip == false)
                        flip = !flip;
                uncheckAll();
                $j(this).parents("#checkboxAll:first").find(":checkbox").attr("checked", flip);
                $j(this).parents("#checkboxAll:first").find(":checkbox").change();
            });

            group.find("#checkboxRadio").find("input[type$='checkbox']").click(function() {
                uncheckAll();
                $j(this).siblings("input[type$='checkbox']").attr("checked", false);
                $j(this).attr("checked", true);
                $j(this).change();
            });

            group.find("#checkboxCheckbox").click(function() {
                uncheckRadioAndAll();
            });
        });
    });
}
